files.content:
:root {
  --background: #ffffff;
  --foreground: #18181b;
  --card: #ffffff;
  --card-foreground: #18181b;
  --primary: #1d4ed8;
  --primary-foreground: #ffffff;
  --muted: #f4f4f5;
  --muted-foreground: #52525b;
  --border: #71717a;
  --ring: #1d4ed8;
  --destructive: #b91c1c;
  --radius: 8px;
  --font-sans: ui-sans-serif, system-ui, sans-serif;
}

.dark {
  --background: #09090b;
  --foreground: #fafafa;
  --card: #18181b;
  --card-foreground: #fafafa;
  --primary: #60a5fa;
  --primary-foreground: #09090b;
  --muted: #18181b;
  --muted-foreground: #d4d4d8;
  --ring: #60a5fa;
  --destructive: #f87171;
}

[data-afferent-screen] {
  box-sizing: border-box;
  color: var(--foreground);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.5;
}

[data-afferent-screen] *,
[data-afferent-screen] *::before,
[data-afferent-screen] *::after {
  box-sizing: inherit;
}

[data-afferent-screen] :focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.afferent-skip-link {
  left: 16px;
  position: fixed;
  top: 0;
  transform: translateY(-150%);
  z-index: 50;
}

.afferent-skip-link:focus {
  background: var(--background);
  color: var(--foreground);
  padding: 8px 16px;
  transform: translateY(8px);
}

.afferent-sr-only {
  border: 0;
  clip: rect(0, 0, 0, 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

.afferent-board {
  margin-inline: auto;
  max-width: 960px;
  padding: 32px 16px 48px;
}

.afferent-board__header {
  align-items: flex-start;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: space-between;
  margin-bottom: 32px;
}

.afferent-board__controls,
.afferent-board__results,
.afferent-composer,
.afferent-similar {
  display: grid;
  gap: 16px;
  margin-bottom: 32px;
}

.afferent-controls-grid {
  display: grid;
  gap: 16px;
}

.afferent-controls-grid label,
.afferent-field {
  display: grid;
  font-size: 14px;
  font-weight: 600;
  gap: 8px;
}

.afferent-controls-grid input,
.afferent-controls-grid select,
.afferent-field input,
.afferent-field textarea {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--foreground);
  font: 400 16px/1.5 var(--font-sans);
  min-height: 44px;
  padding: 8px 16px;
}

.afferent-field textarea {
  min-height: 144px;
  resize: vertical;
}

.afferent-field p,
.afferent-feedback-card__board {
  color: var(--muted-foreground);
  font-size: 14px;
  font-weight: 400;
}

.afferent-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.afferent-actions .afferent-button--secondary {
  margin-top: 0;
}

.afferent-inline-error {
  border: 1px solid var(--destructive);
  border-radius: var(--radius);
  display: grid;
  gap: 8px;
  padding: 16px;
}

.afferent-board__workspace,
.afferent-post-detail,
.afferent-discussion,
.afferent-activity,
.afferent-edit-form,
.afferent-comment-form {
  display: grid;
  gap: 16px;
}

.afferent-post-detail {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  min-width: 0;
  padding: 16px;
}

.afferent-post-detail__board,
.afferent-post-detail__status {
  color: var(--muted-foreground);
  font-size: 14px;
}

.afferent-post-detail__body {
  max-width: 72ch;
  overflow-wrap: anywhere;
}

.afferent-post-detail__metadata,
.afferent-post-detail__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin: 0;
}

.afferent-post-detail__metadata div {
  display: grid;
  gap: 4px;
}

.afferent-post-detail__metadata dt {
  font-size: 14px;
  font-weight: 600;
}

.afferent-post-detail__metadata dd {
  margin: 0;
}

.afferent-post-detail__actions button,
.afferent-discussion button,
.afferent-activity button {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--foreground);
  min-height: 44px;
  padding: 8px 16px;
}

.afferent-button--destructive {
  background: var(--destructive);
  border-color: var(--destructive);
  color: var(--primary-foreground);
}

.afferent-discussion__list,
.afferent-activity ol {
  display: grid;
  gap: 16px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.afferent-comment {
  border-inline-start: 2px solid var(--border);
  padding-inline-start: 16px;
  scroll-margin-block-start: 24px;
}

.afferent-comment--reply {
  margin-inline-start: 24px;
}

.afferent-comment-form label,
.afferent-edit-form label {
  display: grid;
  font-size: 14px;
  font-weight: 600;
  gap: 8px;
}

.afferent-comment-form textarea,
.afferent-edit-form input,
.afferent-edit-form textarea {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--foreground);
  font: 400 16px/1.5 var(--font-sans);
  min-height: 44px;
  padding: 8px 16px;
}

.afferent-post-detail dialog {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--foreground);
  max-width: min(480px, calc(100% - 32px));
  padding: 24px;
}

.afferent-board h1 {
  font-size: 28px;
  font-weight: 600;
  line-height: 1.2;
  margin: 0 0 8px;
}

.afferent-board h2 {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
  margin: 0;
}

.afferent-board p {
  margin: 0;
}

.afferent-button {
  align-items: center;
  background: var(--primary);
  border: 1px solid var(--primary);
  border-radius: var(--radius);
  color: var(--primary-foreground);
  display: inline-flex;
  font: 600 16px/1.5 var(--font-sans);
  gap: 8px;
  justify-content: center;
  min-height: 44px;
  padding: 8px 16px;
}

.afferent-button svg {
  height: 20px;
  width: 20px;
}

.afferent-button--secondary {
  background: var(--background);
  border-color: var(--border);
  color: var(--foreground);
  margin-top: 24px;
}

.afferent-button:disabled {
  opacity: 0.65;
}

.afferent-board__list {
  display: grid;
  gap: 16px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.afferent-feedback-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: grid;
  gap: 16px;
  padding: 16px;
}

.afferent-feedback-card a {
  color: var(--foreground);
  text-decoration: underline;
  text-underline-offset: 4px;
}

.afferent-feedback-card__content {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.afferent-feedback-card__body {
  max-width: 72ch;
  overflow-wrap: anywhere;
}

.afferent-feedback-card__status {
  color: var(--muted-foreground);
  font-size: 14px;
}

.afferent-feedback-card__totals {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin: 0;
}

.afferent-feedback-card__totals div {
  align-items: center;
  display: flex;
  gap: 8px;
}

.afferent-feedback-card__totals dt {
  align-items: center;
  display: flex;
  font-size: 14px;
  font-weight: 600;
  gap: 4px;
}

.afferent-feedback-card__totals dd {
  font-size: 14px;
  margin: 0;
}

.afferent-feedback-card__totals svg {
  height: 16px;
  width: 16px;
}

.afferent-state {
  background: var(--muted);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: grid;
  gap: 8px;
  padding: 24px;
}

.afferent-state__action {
  margin-top: 8px;
}

.afferent-roadmap,
.afferent-changelog,
.afferent-notifications {
  display: grid;
  gap: 32px;
  margin-inline: auto;
  max-width: 1200px;
  padding: 32px 16px 48px;
}

.afferent-public-header {
  align-items: end;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: space-between;
}

.afferent-public-header h1,
.afferent-roadmap h1,
.afferent-changelog h1,
.afferent-notifications h1 {
  font-size: 28px;
  font-weight: 600;
  line-height: 1.2;
  margin: 0 0 8px;
}

.afferent-public-header p,
.afferent-roadmap p,
.afferent-changelog p,
.afferent-notifications p {
  margin: 0;
}

.afferent-public-header label {
  display: grid;
  font-size: 14px;
  font-weight: 600;
  gap: 8px;
}

.afferent-public-header select {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--foreground);
  font: 400 16px/1.5 var(--font-sans);
  min-height: 44px;
  padding: 8px 16px;
}

.afferent-roadmap__groups,
.afferent-roadmap-group,
.afferent-changelog__list,
.afferent-changelog__detail {
  display: grid;
  gap: 16px;
}

.afferent-roadmap-group {
  align-content: start;
  background: var(--muted);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  min-width: 0;
  padding: 16px;
}

.afferent-roadmap-group > header {
  align-items: center;
  display: flex;
  justify-content: space-between;
}

.afferent-roadmap-group h2,
.afferent-changelog-entry h2,
.afferent-changelog-entry h3 {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
  margin: 0;
}

.afferent-roadmap-group__list,
.afferent-changelog__list,
.afferent-changelog-entry ol {
  display: grid;
  gap: 16px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.afferent-roadmap-card,
.afferent-changelog-entry {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: grid;
  gap: 16px;
  min-width: 0;
  padding: 16px;
}

.afferent-roadmap-card a,
.afferent-changelog-entry a {
  color: var(--foreground);
  text-decoration: underline;
  text-underline-offset: 4px;
}

.afferent-roadmap-card__status,
.afferent-roadmap-card__board,
.afferent-changelog-entry time,
.afferent-changelog-entry li span {
  color: var(--muted-foreground);
  font-size: 14px;
}

.afferent-roadmap-card__totals {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin: 0;
}

.afferent-roadmap-card__totals div {
  display: grid;
  gap: 4px;
}

.afferent-roadmap-card__totals dt {
  font-size: 14px;
  font-weight: 600;
}

.afferent-roadmap-card__totals dd {
  margin: 0;
}

.afferent-changelog-entry__body {
  max-width: 72ch;
  overflow-wrap: anywhere;
}

.afferent-changelog-entry li {
  align-items: baseline;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.afferent-notifications__list {
  display: grid;
  gap: 16px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.afferent-notification {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: grid;
  gap: 12px;
  min-width: 0;
  padding: 16px;
}

.afferent-notification[data-notification-unread="true"] {
  border-inline-start: 4px solid var(--primary);
}

.afferent-notification > header {
  align-items: baseline;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: space-between;
}

.afferent-notification a {
  color: var(--foreground);
  font-weight: 600;
  overflow-wrap: anywhere;
  text-decoration: underline;
  text-underline-offset: 4px;
}

.afferent-notification__type,
.afferent-notification__metadata {
  color: var(--muted-foreground);
  font-size: 14px;
}

.afferent-notifications-popover {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 12px 32px rgb(0 0 0 / 18%);
  color: var(--foreground);
  max-height: min(640px, calc(100vh - 32px));
  max-width: calc(100vw - 32px);
  overflow: auto;
  width: 400px;
  z-index: 50;
}

.afferent-notifications-popover .afferent-notifications {
  gap: 24px;
  padding: 24px;
}

.afferent-notifications-trigger__count {
  align-items: center;
  background: var(--primary-foreground);
  border-radius: 999px;
  color: var(--primary);
  display: inline-flex;
  font-size: 12px;
  justify-content: center;
  min-height: 20px;
  min-width: 20px;
  padding-inline: 6px;
}

@media (min-width: 640px) {
  .afferent-board {
    padding-inline: 32px;
  }

  .afferent-feedback-card {
    grid-template-columns: minmax(0, 1fr) auto;
    padding: 24px;
  }

  .afferent-controls-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .afferent-roadmap,
  .afferent-changelog,
  .afferent-notifications {
    padding-inline: 32px;
  }

  .afferent-roadmap-card,
  .afferent-changelog-entry,
  .afferent-notification {
    padding: 24px;
  }
}

@media (min-width: 768px) {
  .afferent-roadmap__groups {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .afferent-board__workspace {
    align-items: start;
    grid-template-columns: minmax(320px, 2fr) minmax(320px, 3fr);
  }

  .afferent-post-detail {
    padding: 24px;
  }
}

@media (pointer: coarse) {
  .afferent-button,
  .afferent-public-header select,
  .afferent-notification button {
    min-height: 44px;
    min-width: 44px;
  }
}

@media (min-width: 1024px) {
  .afferent-board {
    max-width: 1200px;
  }
}

.afferent-admin {
  display: grid;
  gap: 24px;
  margin-inline: auto;
  max-width: 1280px;
  padding: 32px 16px 48px;
}
.afferent-admin-workspace,
.afferent-admin-detail,
.afferent-admin-form,
.afferent-changelog-editor,
.afferent-changelog-editor form {
  display: grid;
  gap: 16px;
}
.afferent-admin-queue {
  display: grid;
  gap: 8px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.afferent-admin-queue button {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--foreground);
  display: grid;
  gap: 4px;
  padding: 16px;
  text-align: start;
  width: 100%;
}
.afferent-admin-queue [data-admin-label]::before {
  color: var(--muted-foreground);
  content: attr(data-admin-label) ": ";
  font-size: 14px;
}
.afferent-admin-form label,
.afferent-changelog-editor label,
.afferent-dialog label {
  display: grid;
  font-weight: 600;
  gap: 8px;
}
.afferent-admin input,
.afferent-admin textarea,
.afferent-admin select,
.afferent-dialog input,
.afferent-dialog select {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--foreground);
  min-height: 44px;
  padding: 8px 12px;
}
.afferent-dialog-overlay {
  background: rgb(0 0 0 / 50%);
  inset: 0;
  position: fixed;
  z-index: 60;
}
.afferent-dialog {
  background: var(--background);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  color: var(--foreground);
  display: grid;
  gap: 16px;
  left: 50%;
  max-height: calc(100vh - 32px);
  max-width: calc(100vw - 32px);
  overflow: auto;
  padding: 24px;
  position: fixed;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 480px;
  z-index: 61;
}
@media (min-width: 768px) {
  .afferent-admin-workspace {
    align-items: start;
    grid-template-columns: minmax(280px, 35fr) minmax(0, 65fr);
  }
  .afferent-changelog-editor {
    grid-column: 1 / -1;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-afferent-screen] *,
  [data-afferent-screen] *::before,
  [data-afferent-screen] *::after {
    animation-duration: 0.01ms !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

@media (forced-colors: active) {
  [data-afferent-screen] :focus-visible {
    outline-color: Highlight;
  }
}

"use client";

import { createContext, useContext, useMemo, type ReactNode } from "react";

import {
  mergeAfferentUiCopy,
  type AfferentUiCopy,
  type DeepPartial,
} from "@/components/afferent/core/copy";
import {
  defaultAfferentIcons,
  type AfferentIconSlots,
} from "@/components/afferent/core/icons";
import {
  NativeAfferentLink,
  type AfferentHrefBuilder,
  type AfferentLinkComponent,
  type AfferentNavigation,
} from "@/components/afferent/core/navigation";

export type AfferentUiContextValue = Readonly<{
  copy: AfferentUiCopy;
  icons: AfferentIconSlots;
  navigation: AfferentNavigation;
}>;

const AfferentUiContext = createContext<AfferentUiContextValue | undefined>(
  undefined,
);

export function AfferentUiProvider({
  children,
  copy,
  icons,
  href,
  Link = NativeAfferentLink,
  navigate,
  currentLocation,
}: Readonly<{
  children: ReactNode;
  copy?: DeepPartial<AfferentUiCopy>;
  icons?: Partial<AfferentIconSlots>;
  href: AfferentHrefBuilder;
  Link?: AfferentLinkComponent;
  navigate?: (href: string) => void;
  currentLocation: string;
}>) {
  const value = useMemo<AfferentUiContextValue>(
    () => ({
      copy: mergeAfferentUiCopy(copy),
      icons: { ...defaultAfferentIcons, ...icons },
      navigation: { href, Link, navigate, currentLocation },
    }),
    [copy, icons, href, Link, navigate, currentLocation],
  );
  return (
    <AfferentUiContext.Provider value={value}>
      {children}
    </AfferentUiContext.Provider>
  );
}

export function useAfferentUi() {
  const value = useContext(AfferentUiContext);
  if (!value) {
    throw new Error("useAfferentUi requires an AfferentUiProvider");
  }
  return value;
}

