    notAuthorizedHeading: string;
    notAuthorizedBody: string;
    unsupportedHeading: string;
    unsupportedBody: string;
    loading: string;
    loadingParticipation: string;
    tryLoadingAgain: string;
    dismissError: string;
  }>;
  board: Readonly<{
    title: string;
    description: string;
    createFeedback: string;
    postFeedback: string;
    returnToFeedback: string;
    postingFeedback: string;
    browseHeading: string;
    resultsHeading: string;
    boardLabel: string;
    allBoards: string;
    searchLabel: string;
    statusLabel: string;
    allStatuses: string;
    sortLabel: string;
    titleLabel: string;
    titleHelp: string;
    bodyLabel: string;
    bodyHelp: string;
    createHelp: string;
    signInToCreate: string;
    createErrorHeading: string;
    similarHeading: string;
    similarHelp: string;
    loadingSimilar: string;
    noSimilarHeading: string;
    noSimilarBody: string;
    similarErrorHeading: string;
    loadingSearch: string;
    searchErrorHeading: string;
    searchResultsLabel: string;
    skipToFeedback: string;
    resultCount: (count: number) => string;
    emptyHeading: string;
    emptyBody: string;
    noMatchesHeading: string;
    noMatchesBody: string;
    clearFilters: string;
    loadErrorHeading: string;
    loadErrorBody: string;
    loadMore: string;
    loadingMore: string;
    voteCount: (count: number) => string;
    commentCount: (count: number) => string;
  }>;
  detail: Readonly<{
    loading: string;
    loadErrorHeading: string;
    notFoundHeading: string;
    notFoundBody: string;
    returnToFeedback: string;
    mergedHeading: string;
    mergedBody: string;
    viewCanonical: string;
    votes: string;
    comments: string;
    author: string;
    signInBody: string;
    vote: string;
    removeVote: string;
    subscribe: string;
    unsubscribe: string;
    edit: string;
    withdraw: string;
    editTitle: string;
    editBody: string;
    saveChanges: string;
    returnToPost: string;
    withdrawTitle: (title: string) => string;
    withdrawBody: string;
    keepFeedback: string;
  }>;
  discussion: Readonly<{
    heading: string;
    loading: string;
    emptyHeading: string;
    emptyBody: string;
    loadErrorHeading: string;
    loadMore: string;
    loadingMore: string;
    anonymousAuthor: string;
    reply: string;
    commentLabel: string;
    replyLabel: string;
